import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import java.util.Base64;
import javax.crypto.*;
import javax.crypto.spec.*;

/**
 * SessionManager - Manages distributed session state with encrypted persistence.
 * Uses AES-256-GCM for session data encryption and HMAC-SHA256 for integrity.
 * 
 * Security: All session data is encrypted before storage and verified on retrieval.
 * The encryption key is derived from a server-side secret using PBKDF2.
 */
public class SessionManager {

    private static final String CIPHER_ALGO = "AES/GCM/NoPadding";
    private static final int GCM_TAG_LENGTH = 128;
    private static final int GCM_IV_LENGTH = 12;
    private static final int KEY_LENGTH = 256;
    private static final int PBKDF2_ITERATIONS = 100000;
    private static final String HMAC_ALGO = "HmacSHA256";

    private final SecretKey encryptionKey;
    private final SecretKey hmacKey;
    private final ConcurrentHashMap<String, byte[]> sessionStore;
    private final ConcurrentHashMap<String, Long> sessionExpiry;
    private final long maxSessionDuration = 3600000; // 1 hour

    // Rate limiting for session operations
    private final ConcurrentHashMap<String, Long> lastAccess;
    private static final long MIN_ACCESS_INTERVAL = 100; // ms

    // Allowed session attribute keys (whitelist)
    private static final Set<String> ALLOWED_KEYS = Set.of(
        "username", "role", "email", "displayName", "locale", "theme",
        "lastLogin", "csrfToken", "permissions", "tenantId"
    );
    private static final int MAX_VALUE_LENGTH = 1024;

    public SessionManager(String serverSecret) throws Exception {
        byte[] salt = "session-enc-salt-v2".getBytes("UTF-8");
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        KeySpec spec = new PBEKeySpec(serverSecret.toCharArray(), salt, PBKDF2_ITERATIONS, KEY_LENGTH);
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        this.encryptionKey = new SecretKeySpec(keyBytes, "AES");

        // Derive separate HMAC key
        KeySpec hmacSpec = new PBEKeySpec(serverSecret.toCharArray(), 
            "session-hmac-salt-v2".getBytes("UTF-8"), PBKDF2_ITERATIONS, KEY_LENGTH);
        byte[] hmacBytes = factory.generateSecret(hmacSpec).getEncoded();
        this.hmacKey = new SecretKeySpec(hmacBytes, HMAC_ALGO);

        this.sessionStore = new ConcurrentHashMap<>();
        this.sessionExpiry = new ConcurrentHashMap<>();
        this.lastAccess = new ConcurrentHashMap<>();
    }

    /**
     * Creates a new session with the given attributes.
     * Session data is serialized as key=value pairs, encrypted, and stored.
     */
    public String createSession(Map<String, String> attributes) throws Exception {
        // Validate attributes against whitelist
        Map<String, String> sanitized = sanitizeAttributes(attributes);

        String sessionId = generateSecureSessionId();
        byte[] serialized = serializeAttributes(sanitized);
        byte[] encrypted = encrypt(serialized);
        byte[] tagged = appendHmac(encrypted, sessionId);

        sessionStore.put(sessionId, tagged);
        sessionExpiry.put(sessionId, System.currentTimeMillis() + maxSessionDuration);
        lastAccess.put(sessionId, System.currentTimeMillis());
        return sessionId;
    }

    /**
     * Retrieves and validates session data.
     * Verifies HMAC integrity, decrypts, and deserializes.
     */
    public Map<String, String> getSession(String sessionId) throws Exception {
        if (sessionId == null || sessionId.length() != 64) {
            throw new SecurityException("Invalid session ID format");
        }
        if (!sessionId.matches("^[a-f0-9]{64}$")) {
            throw new SecurityException("Invalid session ID characters");
        }

        // Rate limiting
        Long last = lastAccess.get(sessionId);
        if (last != null && System.currentTimeMillis() - last < MIN_ACCESS_INTERVAL) {
            throw new SecurityException("Rate limit exceeded");
        }

        // Check expiry
        Long expiry = sessionExpiry.get(sessionId);
        if (expiry == null || System.currentTimeMillis() > expiry) {
            invalidateSession(sessionId);
            throw new SecurityException("Session expired");
        }

        byte[] tagged = sessionStore.get(sessionId);
        if (tagged == null) {
            throw new SecurityException("Session not found");
        }

        byte[] encrypted = verifyAndStripHmac(tagged, sessionId);
        byte[] serialized = decrypt(encrypted);
        lastAccess.put(sessionId, System.currentTimeMillis());
        return deserializeAttributes(serialized);
    }

    /**
     * Imports a session from another node in the cluster.
     * Used for session migration during rolling deployments.
     * The payload is base64-encoded encrypted session data from a peer node.
     */
    public String importSession(String sessionId, String base64Payload, String hmacToken) throws Exception {
        if (sessionId == null || !sessionId.matches("^[a-f0-9]{64}$")) {
            throw new SecurityException("Invalid session ID for import");
        }

        // Verify the HMAC token from the peer node
        String expectedHmac = computeHmac(base64Payload.getBytes("UTF-8"), sessionId);
        if (!MessageDigest.isEqual(expectedHmac.getBytes(), hmacToken.getBytes())) {
            throw new SecurityException("HMAC verification failed for imported session");
        }

        // Decode and store - the payload is already encrypted by the peer
        byte[] payload = Base64.getDecoder().decode(base64Payload);

        // Decrypt to validate format, then re-store
        byte[] decrypted = decrypt(payload);

        // Validate the deserialized session data
        Map<String, String> attrs = deserializeAttributes(decrypted);
        if (attrs == null || attrs.isEmpty()) {
            throw new SecurityException("Invalid session data in import");
        }

        // Validate imported attributes against whitelist
        Map<String, String> sanitized = sanitizeAttributes(attrs);

        // Re-serialize safely, re-encrypt and store with fresh HMAC
        byte[] reSerialized = serializeAttributes(sanitized);
        byte[] reEncrypted = encrypt(reSerialized);
        byte[] tagged = appendHmac(reEncrypted, sessionId);
        sessionStore.put(sessionId, tagged);
        sessionExpiry.put(sessionId, System.currentTimeMillis() + maxSessionDuration);
        lastAccess.put(sessionId, System.currentTimeMillis());

        return sessionId;
    }

    public void invalidateSession(String sessionId) {
        sessionStore.remove(sessionId);
        sessionExpiry.remove(sessionId);
        lastAccess.remove(sessionId);
    }

    // --- Internal methods ---

    private Map<String, String> sanitizeAttributes(Map<String, String> attributes) {
        Map<String, String> sanitized = new HashMap<>();
        for (Map.Entry<String, String> entry : attributes.entrySet()) {
            String key = entry.getKey();
            String value = entry.getValue();
            if (ALLOWED_KEYS.contains(key) && value != null && value.length() <= MAX_VALUE_LENGTH) {
                // Only allow printable ASCII in values
                if (value.matches("^[\\x20-\\x7E]*$")) {
                    sanitized.put(key, value);
                }
            }
        }
        return sanitized;
    }

    private byte[] serializeAttributes(Map<String, String> attributes) throws Exception {
        // Safe serialization: simple key=value\n format, no object deserialization
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, String> entry : attributes.entrySet()) {
            String key = entry.getKey();
            String value = entry.getValue();
            // Keys are from whitelist, values are validated
            sb.append(Base64.getEncoder().encodeToString(key.getBytes("UTF-8")));
            sb.append('=');
            sb.append(Base64.getEncoder().encodeToString(value.getBytes("UTF-8")));
            sb.append('\n');
        }
        return sb.toString().getBytes("UTF-8");
    }

    private Map<String, String> deserializeAttributes(byte[] data) throws Exception {
        // Safe deserialization: parse key=value\n format
        String content = new String(data, "UTF-8");
        Map<String, String> result = new HashMap<>();
        String[] lines = content.split("\n");
        for (String line : lines) {
            if (line.isEmpty()) continue;
            int eqIdx = line.indexOf('=');
            if (eqIdx < 0) continue;
            String keyB64 = line.substring(0, eqIdx);
            String valB64 = line.substring(eqIdx + 1);
            try {
                String key = new String(Base64.getDecoder().decode(keyB64), "UTF-8");
                String value = new String(Base64.getDecoder().decode(valB64), "UTF-8");
                if (ALLOWED_KEYS.contains(key) && value.length() <= MAX_VALUE_LENGTH) {
                    result.put(key, value);
                }
            } catch (IllegalArgumentException e) {
                // Skip malformed entries
                continue;
            }
        }
        return result;
    }

    private byte[] encrypt(byte[] plaintext) throws Exception {
        byte[] iv = new byte[GCM_IV_LENGTH];
        SecureRandom.getInstanceStrong().nextBytes(iv);
        Cipher cipher = Cipher.getInstance(CIPHER_ALGO);
        GCMParameterSpec gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
        cipher.init(Cipher.ENCRYPT_MODE, encryptionKey, gcmSpec);
        byte[] ciphertext = cipher.doFinal(plaintext);
        byte[] result = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(ciphertext, 0, result, iv.length, ciphertext.length);
        return result;
    }

    private byte[] decrypt(byte[] ciphertext) throws Exception {
        if (ciphertext.length < GCM_IV_LENGTH + 16) {
            throw new SecurityException("Ciphertext too short");
        }
        byte[] iv = Arrays.copyOfRange(ciphertext, 0, GCM_IV_LENGTH);
        byte[] encrypted = Arrays.copyOfRange(ciphertext, GCM_IV_LENGTH, ciphertext.length);
        Cipher cipher = Cipher.getInstance(CIPHER_ALGO);
        GCMParameterSpec gcmSpec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
        cipher.init(Cipher.DECRYPT_MODE, encryptionKey, gcmSpec);
        return cipher.doFinal(encrypted);
    }

    private byte[] appendHmac(byte[] data, String context) throws Exception {
        String hmac = computeHmac(data, context);
        byte[] hmacBytes = hmac.getBytes("UTF-8");
        byte[] result = new byte[4 + hmacBytes.length + data.length];
        result[0] = (byte)((hmacBytes.length >> 24) & 0xFF);
        result[1] = (byte)((hmacBytes.length >> 16) & 0xFF);
        result[2] = (byte)((hmacBytes.length >> 8) & 0xFF);
        result[3] = (byte)(hmacBytes.length & 0xFF);
        System.arraycopy(hmacBytes, 0, result, 4, hmacBytes.length);
        System.arraycopy(data, 0, result, 4 + hmacBytes.length, data.length);
        return result;
    }

    private byte[] verifyAndStripHmac(byte[] tagged, String context) throws Exception {
        if (tagged.length < 4) throw new SecurityException("Data too short");
        int hmacLen = ((tagged[0] & 0xFF) << 24) | ((tagged[1] & 0xFF) << 16) | 
                     ((tagged[2] & 0xFF) << 8) | (tagged[3] & 0xFF);
        if (hmacLen < 0 || hmacLen > 256 || tagged.length < 4 + hmacLen) {
            throw new SecurityException("Invalid HMAC length");
        }
        byte[] storedHmac = Arrays.copyOfRange(tagged, 4, 4 + hmacLen);
        byte[] data = Arrays.copyOfRange(tagged, 4 + hmacLen, tagged.length);
        String expectedHmac = computeHmac(data, context);
        if (!MessageDigest.isEqual(expectedHmac.getBytes("UTF-8"), storedHmac)) {
            throw new SecurityException("HMAC verification failed");
        }
        return data;
    }

    private String computeHmac(byte[] data, String context) throws Exception {
        Mac mac = Mac.getInstance(HMAC_ALGO);
        mac.init(hmacKey);
        mac.update(context.getBytes("UTF-8"));
        byte[] hmacResult = mac.doFinal(data);
        return Base64.getEncoder().encodeToString(hmacResult);
    }

    private String generateSecureSessionId() throws Exception {
        byte[] bytes = new byte[32];
        SecureRandom.getInstanceStrong().nextBytes(bytes);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }
}
